using Jotunn.Configs;
using UnityEngine;

namespace BrudvikWhiteHilt.Items.Foraging.Fireweed;

/// <summary>
/// Fireweed, tall spikes of magenta flowers that are the first green to return to burnt ground, in the Ashlands. Model:
/// generated by AssetSource/Tools/make_forage_models.py. Fiddleheads picked in the Ashlands can also give it.
/// </summary>
public class Fireweed : ForageableBase
{
    /// <summary>
    /// Prefab name of the fireweed item.
    /// </summary>
    public const string PrefabName = "WhiteHiltFireweed";

    /// <inheritdoc/>
    public override string BaseName => PrefabName;

    /// <inheritdoc/>
    protected override string FullName => "Fireweed";

    /// <inheritdoc/>
    protected override string Description => "Tall spikes of magenta flowers, the first green to come back where the land has burned. The young shoots are eaten and the leaves brewed.";

    /// <inheritdoc/>
    protected override string CopyItemFrom => "Thistle";

    /// <inheritdoc/>
    protected override string CopyPickableFrom => "Pickable_Thistle";

    /// <inheritdoc/>
    protected override VegetationConfig Vegetation => new()
    {
        Biome = Heightmap.Biome.AshLands,
        // Groups per zone where the ground suits it; the generator keeps trying spots until they are placed.
        Min = 1,
        Max = 2,
        ForcePlacement = true,
        GroupSizeMin = 2,
        GroupSizeMax = 5,
        GroupRadius = 4f,
        MinAltitude = 1f,
        MaxTilt = 30f,
        ScaleMin = 0.85f,
        ScaleMax = 1.15f,
        BlockCheck = true
    };

    /// <inheritdoc/>
    public override bool Enabled => true;

    /// <inheritdoc/>
    protected override string ExtraDropFrom => "Pickable_Fiddlehead";

    /// <inheritdoc/>
    protected override float ExtraDropChance => 0.25f;

    /// <inheritdoc/>
    protected override void ApplyVisual(GameObject visualRoot)
    {
        ReplacePlantMesh(visualRoot, "fireweed", 1.2f);
    }

    /// <inheritdoc/>
    protected override void ApplyPickableVisual(GameObject pickablePrefab, Pickable pickable)
    {
        RemoveGlow(pickablePrefab);
        base.ApplyPickableVisual(pickablePrefab, pickable);
    }
}
